/* Resets */
/* default base font for most clients */
html {
font-size: 16px;
}
html,
body {
margin: 0 !important;
padding: 0 !important;
height: 100% !important;
width: 100% !important;
}
* {
-ms-text-size-adjust: 100%;
-webkit-text-size-adjust: 100%;
}
table,
td {
mso-table-lspace: 0pt !important;
mso-table-rspace: 0pt !important;
}
table {
border-collapse: collapse !important;
}
img {
-ms-interpolation-mode: bicubic;
border: 0;
height: auto;
line-height: 100%;
outline: none;
text-decoration: none;
}
a {
text-decoration: none;
}
a[x-apple-data-detectors] {
color: inherit !important;
text-decoration: none !important;
}
/* Base typography */
body,
table,
td,
p,
a,
h1,
h2,
h3,
h4 {
font-family: 'Open Sans', sans-serif;
}
/* Gmail iOS right gutter fix */
u+#body a {
color: inherit;
text-decoration: underline;
}
/* Headings */
h2 {
font-size: 1.125em;
line-height: 1.5;
margin: 1em 0 0.5em 0;
color: #0b1a33;
font-weight: 700;
border-left: 4px solid #0b3d91;
padding-left: 10px;
}
h3 {
font-size: 1em;
line-height: 1.25;
margin: 0.5em 0 0.25em 0;
color: #2d2d2d;
font-weight: 600;
}
/* Default: no underline for links in content */
.email-container a {
text-decoration: none;
}
/* But keep footer links underlined */
.footer a {
text-decoration: underline;
}
/* Preview text styling */
.preview-text {
font-size: 0.875em;
line-height: 1.4;
color: #444444;
}
/* Container */
.email-container {
max-width: 800px;
}
/* Desktop defaults */
@media only screen and (max-width: 799px) {
.email-container {
width: 100% !important;
}
.sm-px {
padding-left: 1em !important;
padding-right: 1em !important;
}
.stack-column,
.stack-column td {
display: block !important;
width: 100% !important;
}
